```kotlin
// @file: Parallel fetch of independent vendor prices.
// @consumers: PricingAggregator

package com.example.pricing

import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.async
import kotlinx.coroutines.supervisorScope
import kotlinx.coroutines.withContext

/**
 * @purpose Fetch prices from multiple vendors in parallel, tolerating individual failures.
 * @invariant One vendor failure does not cancel siblings; failed vendors surface as null in the map.
 * @param vendorIds Vendor identifiers to query.
 * @return Map from vendor id to price; null value = vendor failed for this call.
 * @sideEffect Network: parallel GETs to /v1/prices per vendor.
 * @sideEffect Dispatch: injected `io` dispatcher.
 */
class VendorPricing(
    private val _priceClient: PriceClient,
    private val _io: CoroutineDispatcher,
) {
    suspend fun fetchVendorPrices(vendorIds: List): Map =
        withContext(_io) {
            supervisorScope {
                vendorIds.associateWith { id ->
                    async {
                        try {
                            _priceClient.retrievePrice(id)
                        } catch (cancel: CancellationException) {
                            throw cancel
                        } catch (cause: Throwable) {
                            null
                        }
                    }
                }.mapValues { (_, deferred) -> deferred.await() }
            }
        }
}
```

```kotlin
// @file: Background sync service; owns its own coroutine lifetime.

package com.example.sync

import kotlinx.coroutines.CoroutineExceptionHandler
import kotlinx.coroutines.CoroutineName
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.launch

/**
 * @purpose Periodic background sync; owned by DI container, cancelled on `close()`.
 * @invariant `close()` MUST be called by the owner — any launched work leaks otherwise.
 * @invariant Uncaught failures in `launch` children surface through `_exceptions` (never crash the scope).
 * @sideEffect Dispatch: injected `io` dispatcher via `_scope`'s context.
 */
class BackgroundSync(
    private val _io: kotlinx.coroutines.CoroutineDispatcher,
    private val _crash: CrashReporter,
) : AutoCloseable {

    //region START_SCOPE_LIFETIME  @invariant: cancelled in close(); handler catches launch children only
    private val _handler = CoroutineExceptionHandler { _, cause ->
        _crash.report("[BackgroundSync] uncaught coroutine failure", cause)
    }
    private val _scope = CoroutineScope(
        SupervisorJob() + _io + _handler + CoroutineName("background-sync"),
    )
    //endregion END_SCOPE_LIFETIME

    fun schedulePeriodicSync(interval: kotlin.time.Duration) {
        _scope.launch {
            // suspend body — cancellation cooperates via delay + I/O suspend points
        }
    }

    override fun close() {
        _scope.cancel()
    }
}
```

```kotlin
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

class RateBudget(private val _capacity: Int) {

    //region START_STATE  @invariant: `_used` mutated only under `_lock`
    private val _lock = Mutex()
    private var _used: Int = 0
    //endregion END_STATE

    suspend fun tryReserve(amount: Int): Boolean =
        _lock.withLock {
            if (_used + amount > _capacity) {
                false
            } else {
                _used += amount
                true
            }
        }
}
```

```kotlin import kotlinx.coroutines.flow.SharingStarted import kotlinx.coroutines.flow.StateFlow import kotlinx.coroutines.flow.stateIn
class PriceViewModel( _repository: PriceRepository, ) : androidx.lifecycle.ViewModel() {
/** * @purpose Latest price of the watched product. * @invariant `stateIn` scope = viewModelScope → cancelled on onCleared; SharingStarted survives 5 s * of no-subscribers to bridge config change without re-subscribing the upstream. */ val price: StateFlow = _repository .observeCurrentPrice() .stateIn( scope = viewModelScope, started = SharingStarted.WhileSubscribed(5_000), initialValue = null, ) } ```

```kotlin
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow

fun LocationSource.observe(): Flow = callbackFlow {
    val listener = LocationListener { loc -> trySend(loc) }
    registerListener(listener)
    awaitClose { unregisterListener(listener) }
}
